	if len(args) != 0 {
		return usagef("list 不接受参数")
	}
	s, err := loadStore(dir)
	if err != nil {
		return err
	}
	if len(s.Assets) == 0 {
		fmt.Println("没有记录")
		return nil
	}
	ids := make([]string, 0, len(s.Assets))
	for id := range s.Assets {
		ids = append(ids, id)
	}
	sort.Strings(ids)
	for _, id := range ids {
		a := s.Assets[id]
		fmt.Printf("%s\t%s\t%s\t%s\n", a.ID, a.Name, a.Location, a.Status)
	}
	return nil
